<?php require __DIR__.'/_nav.php'; $url=\OC::$server->get(\OCP\IURLGenerator::class); $money=static fn($v):string=>number_format((float)$v,2,',','.').' €'; ?>
<div id="app-content"><div class="erp-page erp-finance-page"><div class="erp-head"><div><span class="erp-eyebrow">FINANZEN</span><h1>Kasse</h1><p class="erp-sub">Nachvollziehbares Kassenbuch für Barbewegungen. Buchungen werden storniert statt gelöscht.</p></div></div>
<?php if(!empty($_['message'])):?><div class="erp-notice"><?php p($_['message']);?></div><?php endif;?><?php if(!empty($_['error'])):?><div class="erp-notice erp-notice-warning"><?php p($_['error']);?></div><?php endif;?>
<section class="erp-finance-kpis erp-wide"><div class="erp-finance-kpi"><span>Kassenbestand</span><strong><?php p($money($_['balance']??0));?></strong><small>aus aktiven Buchungen</small></div><div class="erp-finance-kpi"><span>Bareinnahmen</span><strong><?php p($money($_['income']??0));?></strong></div><div class="erp-finance-kpi"><span>Barausgaben</span><strong><?php p($money($_['expense']??0));?></strong></div><div class="erp-finance-kpi <?php if(($_['balance']??0)<0)p('is-warning');?>"><span>Plausibilität</span><strong><?php p(($_['balance']??0)<0?'Prüfen':'OK');?></strong><small><?php p(($_['balance']??0)<0?'Kassenbestand ist rechnerisch negativ.':'Kein negativer Endbestand.');?></small></div></section>
<section class="erp-card erp-wide"><h2>Neue Kassenbuchung</h2><form method="post" action="<?php p($url->linkToRoute('reinhardterp.document.cashAdd'));?>" class="erp-finance-cash-form"><input type="hidden" name="requesttoken" value="<?php p($_['requesttoken']);?>"><label>Datum<input type="date" name="entryDate" value="<?php p(date('Y-m-d'));?>" required></label><label>Art<select name="entryType" required><option value="income">Einnahme</option><option value="expense">Ausgabe</option><option value="opening">Anfangsbestand</option></select></label><label>Betrag €<input type="number" name="amount" min="0.01" step="0.01" required></label><label>USt.<select name="vatRate"><option value="0">0 %</option><option value="7">7 %</option><option value="19" selected>19 %</option></select></label><label>Belegnummer<input name="receiptNo" maxlength="64"></label><label>Kategorie<input name="category" maxlength="120" placeholder="z. B. Material, Porto"></label><label class="erp-cash-wide">Beschreibung<input name="description" maxlength="500" required></label><div class="erp-cash-wide"><button class="button primary" type="submit">Kassenbuchung speichern</button></div></form></section>
<section class="erp-card erp-wide"><h2>Kassenbuch</h2><?php if(empty($_['entries'])):?><p class="erp-muted">Noch keine Kassenbuchungen vorhanden.</p><?php else:?><div class="erp-cash-list"><div class="erp-cash-row erp-cash-head"><span>Datum</span><span>Beleg</span><span>Beschreibung</span><span>Art</span><span>Betrag</span><span>Bestand</span><span></span></div><?php foreach($_['entries'] as $e):$cancel=!empty($e['cancelled_at']);?><div class="erp-cash-row <?php if($cancel)p('is-cancelled');?>"><span><?php p(date('d.m.Y',strtotime($e['entry_date'])));?></span><span><?php p($e['receipt_no']??'–');?></span><span><strong><?php p($e['description']);?></strong><small><?php p(($e['category']??'').(!empty($e['vat_rate'])?' · USt. '.number_format((float)$e['vat_rate'],0).'%':''));?><?php if($cancel):?> · STORNIERT: <?php p($e['cancel_reason']??'');?><?php endif;?></small></span><span><?php p($e['entry_type']==='expense'?'Ausgabe':($e['entry_type']==='opening'?'Anfang':'Einnahme'));?></span><span><?php p($money($e['amount']));?></span><span><?php p($money($e['running_balance']??0));?></span><span><?php if(!$cancel):?><form method="post" action="<?php p($url->linkToRoute('reinhardterp.document.cashCancel',['id'=>$e['id']]));?>" onsubmit="return confirm('Kassenbuchung wirklich stornieren? Der ursprüngliche Eintrag bleibt erhalten und kann nicht wiederhergestellt werden.');"><input type="hidden" name="requesttoken" value="<?php p($_['requesttoken']);?>"><input name="reason" required placeholder="Stornogrund"><button class="button" type="submit">Stornieren</button></form><?php endif;?></span></div><?php endforeach;?></div><?php endif;?></section></div></div>
